import {STAGES,MATERIAL_STATES,KEY,parseBackup,backup,mergeRecords,daysLeft,filtered,csv,updateStage,demoRecords,validateRecord} from './core.mjs';
const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let storageVersion=null;
let records=[],dueOnly=false,selected=null,storageProblem=false;
function tell(message){$('#status').textContent=message;$('#status').style.display='block';setTimeout(()=>$('#status').style.display='none',6500);}
try{const raw=localStorage.getItem(KEY);storageVersion=raw;if(raw)records=parseBackup(raw);}catch{storageProblem=true;tell('Stored data could not be read. Writing is disabled to protect it. Export/recover the existing storage before continuing.');}
function save(next){try{if(storageProblem)throw Error('Storage recovery is required before editing');if(localStorage.getItem(KEY)!==storageVersion)throw Error('Another tab changed your applications. Reload this page before editing; your pending changes were not saved.');const text=backup(next);localStorage.setItem(KEY,text);storageVersion=text;records=next;render();return true;}catch(e){tell('Not saved: '+e.message);return false;}}
for(const stage of STAGES){for(const selector of ['#stage','#form [name=stage]']){const o=el('option',stage);o.value=stage;$(selector).append(o);}}
function isActive(r){return !['closed','offer'].includes(r.stage);}
function near(r){const d=daysLeft(r.deadline);return isActive(r)&&d!==null&&d>=0&&d<=14;}
function render(){
 $('#active-count').textContent=records.filter(isActive).length;$('#due-count').textContent=records.filter(near).length;$('#material-count').textContent=records.filter(isActive).reduce((n,r)=>n+r.materials.filter(m=>m.status!=='ready').length,0);$('#interview-count').textContent=records.filter(r=>['interview','offer'].includes(r.stage)).length;
 const prior=$('#country').value;$('#country').replaceChildren();const all=el('option','All countries');all.value='all';$('#country').append(all);for(const c of [...new Set(records.map(r=>r.country).filter(Boolean))].sort()){const o=el('option',c);o.value=c;$('#country').append(o);}$('#country').value=[...$('#country').options].some(o=>o.value===prior)?prior:'all';
 let rows=filtered(records,{query:$('#query').value,stage:$('#stage').value,country:$('#country').value});if(dueOnly)rows=rows.filter(near);rows.sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));
 $('#result-count').textContent=`${rows.length} shown · ${records.length} total · stages are manually recorded`;
 $('#filter-mode').textContent=dueOnly?'Due within 14 days':'';$('#board').replaceChildren();$('#demo').disabled=records.length>0||storageProblem;
 if(!rows.length){const box=el('div',undefined,'empty');box.append(el('h3',records.length?'No opportunities match these filters.':'A little structure for a big next step.'),el('p',records.length?'Change the search or stage to see your other records.':'Add your first opportunity, or try clearly fictional examples.'));$('#board').append(box);}
 for(const r of rows){const card=el('article',undefined,'card'),badge=el('span',r.stage,'badge');badge.dataset.stage=r.stage;card.append(badge,el('h3',r.title),el('div',r.institution,'institution'),el('div',[r.country||'Country not recorded',r.type].join(' · '),'meta'));
 const d=daysLeft(r.deadline);card.append(el('div',d===null?'No deadline recorded':`${r.deadline} · ${d<0?'past date — recheck source':d===0?'today (UTC date)':d+' days left'}`,'deadline '+(d<0?'expired':d!==null&&d<=14?'urgent':'')));
 const done=r.materials.filter(m=>m.status==='ready').length;card.append(el('div',`${done} / ${r.materials.length} materials ready`,'meta'));const progress=el('div',undefined,'progress'),fill=el('i');fill.style.width=(r.materials.length?done/r.materials.length*100:0)+'%';progress.append(fill);card.append(progress,el('div',r.verified?'Source checked by you':'Source not marked checked','meta'));
 if(r.url){const a=el('a','Open source ↗');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a);}
 const actions=el('div',undefined,'actions');for(const [label,fn] of [['Checklist & notes',()=>showDetails(r.id)],['Edit',()=>edit(r)]]){const b=el('button',label);b.addEventListener('click',fn);actions.append(b);}card.append(actions);$('#board').append(card);}
}
function edit(record){const form=$('#form');form.reset();form.elements.id.value=record?.id||'';for(const key of ['title','institution','country','type','deadline','stage','url','notes'])if(record)form.elements[key].value=record[key];if(!record)form.elements.stage.value='saved';form.elements.verified.checked=!!record?.verified;form.elements.materialLabels.value=record?record.materials.map(m=>m.label).join('\n'):'CV\nMotivation letter\nTranscript';$('#editor-title').textContent=record?'Edit opportunity':'Add an opportunity';$('#editor').showModal();}
$('#form').addEventListener('submit',event=>{event.preventDefault();try{const f=event.currentTarget.elements,prior=records.find(r=>r.id===f.id.value),labels=f.materialLabels.value.split('\n').map(s=>s.trim()).filter(Boolean);if(new Set(labels).size!==labels.length)throw Error('Checklist labels must be unique');const at=new Date().toISOString();let row={id:prior?.id||crypto.randomUUID(),history:prior?.history||[],materials:labels.map(label=>({label,status:prior?.materials.find(m=>m.label===label)?.status||'missing'})),verified:f.verified.checked};for(const key of ['title','institution','country','type','deadline','stage','url','notes'])row[key]=f[key].value;row.history=[...row.history,{at,action:prior?'Opportunity edited manually':'Opportunity created manually'}];row=validateRecord(row);if(save(prior?records.map(r=>r.id===prior.id?row:r):[...records,row])){$('#editor').close();tell('Saved in this browser profile.');}}catch(e){tell(e.message);}});
function showDetails(id){selected=id;const r=records.find(r=>r.id===id);$('#detail-title').textContent=r.title;const box=$('#detail-content');box.replaceChildren();box.append(el('p',r.institution));const stageLabel=el('label','Manually recorded stage '),stage=el('select');for(const s of STAGES){const option=el('option',s);option.value=s;stage.append(option);}stage.value=r.stage;stage.addEventListener('change',()=>{try{if(save(records.map(x=>x.id===id?updateStage(x,stage.value):x)))showDetails(id);}catch(e){tell(e.message);}});stageLabel.append(stage);box.append(stageLabel,el('h3','Materials checklist'));
 for(let i=0;i<r.materials.length;i++){const m=r.materials[i],line=el('div',undefined,'material'),select=el('select');select.setAttribute('aria-label',m.label+' preparation status');for(const s of MATERIAL_STATES){const o=el('option',s);o.value=s;select.append(o);}select.value=m.status;select.addEventListener('change',()=>{const next=records.map(x=>x.id!==id?x:{...x,materials:x.materials.map((v,j)=>i===j?{...v,status:select.value}:v),history:[...x.history,{at:new Date().toISOString(),action:'Checklist changed: '+m.label+' → '+select.value}]});if(!save(next))select.value=m.status;});line.append(el('span',m.label),select);box.append(line);}
 box.append(el('h3','Planning notes'),el('p',r.notes||'No notes yet.','detail-notes'),el('h3','Local activity history'));for(const h of [...r.history].reverse().slice(0,20))box.append(el('p',h.at+' · '+h.action,'history'));box.append(el('p','History is local, editable backup data — not an immutable audit or proof of external submission.','history'));if(!$('#details').open)$('#details').showModal();}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#add').onclick=()=>edit();$('#cancel').onclick=()=>$('#editor').close();$('#close-details').onclick=()=>$('#details').close();for(const s of ['#query','#stage','#country'])$(s).addEventListener('input',render);
$('#all-view').onclick=()=>{dueOnly=false;$('#all-view').classList.add('active');$('#due-view').classList.remove('active');render();};$('#due-view').onclick=()=>{dueOnly=true;$('#due-view').classList.add('active');$('#all-view').classList.remove('active');render();};
$('#demo').onclick=()=>{if(records.length)return tell('Examples only load into an empty workspace; your records were not changed.');save(demoRecords());};
$('#export').onclick=()=>{if(confirm('The backup contains your planning notes. It is not encrypted. Save it privately?'))download(backup(records),'application-board-backup.json','application/json');};
$('#csv').onclick=()=>{if(confirm('CSV includes notes and source URLs. Export a private, unencrypted copy?'))download(csv(records),'application-board.csv','text/csv');};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>1500000)throw Error('Backup exceeds 1.5 MB');const incoming=parseBackup(await file.text());if(confirm(`Merge ${incoming.length} records? Existing IDs cause rejection, never overwrite.`)){if(save(mergeRecords(records,incoming)))tell('Imported without replacing existing records.');}}catch(e){tell('Import rejected: '+e.message);}finally{event.target.value='';}};
$('#privacy').onclick=()=>alert('Records are stored unencrypted in this browser profile, not in a cloud account. Other people using this profile can access them. No analytics, model calls, document uploads, scraping, email or submission integrations are included. Browser data clearing can erase records: export private backups. This first release is not a multi-user server. Check official deadlines, eligibility and funding yourself.');
render();
